package checkout

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"strings"
	"testing"
)

func TestBrowserReadOnlySuccessGuards(t *testing.T) {
	for _, tc := range []string{"paid", "open", "expired", "missing_intent", "wrong_session", "wrong_merchant", "wrong_amount", "wrong_currency", "wrong_product", "wrong_return", "wrong_received", "pending"} {
		t.Run(tc, func(t *testing.T) {
			v, r, plan, proof := manualFixture(t)
			var page map[string]any
			json.Unmarshal(proof.Page, &page)
			page["status"] = "complete"
			page["payment_status"] = "paid"
			intent := page["payment_intent"].(map[string]any)
			intent["status"] = "succeeded"
			intent["amount_received"] = plan.Minor
			switch tc {
			case "open", "expired":
				page["status"] = tc
				page["payment_status"] = "unpaid"
				page["payment_intent"] = nil
			case "missing_intent":
				delete(page, "payment_intent")
			case "wrong_session":
				page["session_id"] = "cs_live_Other"
			case "wrong_merchant":
				page["account_settings"].(map[string]any)["account_id"] = "acct_Other"
			case "wrong_amount":
				page["total_summary"].(map[string]any)["total"] = 1
			case "wrong_currency":
				page["currency"] = "eur"
			case "wrong_product":
				page["line_item_group"].(map[string]any)["line_items"].([]any)[0].(map[string]any)["price"].(map[string]any)["product"].(map[string]any)["id"] = "prod_Other"
			case "wrong_return":
				page["success_url"] = "https://x.com/other/gift-premium/success"
			case "wrong_received":
				intent["amount_received"] = 1
			case "pending":
				page["status"] = "open"
				page["payment_status"] = "unpaid"
				intent["status"] = "processing"
			}
			body, _ := json.Marshal(page)
			calls := 0
			s := &stripeClient{vault: v, key: "pk_live_Test", http: &http.Client{Transport: stripeRoundTrip(func(req *http.Request) (*http.Response, error) {
				if req.Method != "GET" || !strings.HasSuffix(req.URL.Path, "/payment_pages/cs_live_Test") {
					t.Fatal("non-read payment request")
				}
				calls++
				return &http.Response{StatusCode: 200, Header: http.Header{}, Body: io.NopCloser(strings.NewReader(string(body)))}, nil
			})}}
			paid, err := s.verifiedCheckoutPaid(context.Background(), r, plan)
			if calls != 1 {
				t.Fatal("unexpected requests")
			}
			if tc == "paid" {
				if !paid || err != nil {
					t.Fatal("browser payment missed")
				}
			} else if paid {
				t.Fatal("unverified success accepted")
			}
			if tc != "paid" && tc != "open" && tc != "expired" && tc != "pending" && err == nil {
				t.Fatal("mismatch not rejected")
			}
		})
	}
}

func TestInactiveLinkedIntentNeverCreatesOrConfirms(t *testing.T) {
	for _, tc := range []string{"success", "missing_secret", "wrong_intent", "wrong_received", "pending", "wrong_merchant"} {
		t.Run(tc, func(t *testing.T) {
			v, r, plan, proof := manualFixture(t)
			raw := string(proof.Page)
			if tc == "missing_secret" {
				raw = strings.ReplaceAll(raw, "pi_Test_secret_Synthetic", "")
			}
			if tc == "wrong_merchant" {
				raw = strings.ReplaceAll(raw, "acct_Test", "acct_Other")
			}
			v.Put("checkout-verification:"+r.SessionID, []byte(raw))
			calls := 0
			s := &stripeClient{vault: v, key: "pk_live_Test", http: &http.Client{Transport: stripeRoundTrip(func(req *http.Request) (*http.Response, error) {
				if req.Method != "GET" {
					t.Fatal("non-read request")
				}
				calls++
				code := 400
				body := `{"error":{"type":"invalid_request_error","code":"checkout_not_active_session","message":"inactive"}}`
				if strings.HasSuffix(req.URL.Path, "/payment_intents/pi_Test") {
					code = 200
					id := "pi_Test"
					received := plan.Minor
					state := "succeeded"
					if tc == "wrong_intent" {
						id = "pi_Other"
					}
					if tc == "wrong_received" {
						received = 1
					}
					if tc == "pending" {
						state = "processing"
					}
					b, _ := json.Marshal(map[string]any{"id": id, "status": state, "currency": "usd", "amount": plan.Minor, "amount_received": received, "livemode": true})
					body = string(b)
				} else if !strings.HasSuffix(req.URL.Path, "/poll") {
					t.Fatal("unexpected endpoint")
				}
				return &http.Response{StatusCode: code, Header: http.Header{}, Body: io.NopCloser(strings.NewReader(body))}, nil
			})}}
			paid, err := s.verifiedCheckoutPaid(context.Background(), r, plan)
			if tc == "success" {
				if !paid || err != nil || calls != 2 {
					t.Fatal("linked success missed")
				}
			} else if paid || err == nil {
				t.Fatal("unverified linked result accepted")
			}
		})
	}
}

func TestCheckoutLinkBlocksCompletedAndUnknown(t *testing.T) {
	r := &Record{SessionID: "cs_live_Test", URL: "https://checkout.stripe.com/a/pay/cs_live_Test"}
	for _, status := range []string{"succeeded", "unknown", "submitting", "declined", "creating"} {
		r.Status = status
		if CheckoutLink(r) != "" {
			t.Fatal("unsafe link exported")
		}
	}
	r.Status = "created"
	r.LinkBlocked = true
	if CheckoutLink(r) != "" {
		t.Fatal("known stale link exported")
	}
	r.LinkBlocked = false
	if CheckoutLink(r) == "" {
		t.Fatal("valid created link hidden")
	}
}

package checkout

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"
	"testing"
	"time"
	"xgift/internal/proxy"
)

func TestNetworkFailoverOnlyReplaysSafeRequests(t *testing.T) {
	for _, tc := range []struct {
		name, method, path     string
		status                 int
		wantCalls, wantCooling int
	}{
		{"poll", "GET", "payment_pages/cs_live_Test/poll", 0, 2, 1},
		{"init", "POST", "payment_pages/cs_live_Test/init", 0, 2, 1},
		{"confirm", "POST", "payment_pages/cs_live_Test/confirm", 0, 1, 1},
		{"tokenize", "POST", "payment_methods", 0, 1, 1},
		{"decline", "POST", "payment_pages/cs_live_Test/confirm", 402, 1, 0},
		{"forbidden", "GET", "payment_pages/cs_live_Test/poll", 403, 1, 0},
		{"rate_limit", "GET", "payment_pages/cs_live_Test/poll", 429, 1, 0},
		{"server_error", "GET", "payment_pages/cs_live_Test/poll", 500, 1, 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			v := controlFixture(t)
			v.Put("payment-outbounds", []byte(twoPaymentNodes))
			route, e := selectPaymentRoute(v, "1234")
			if e != nil {
				t.Fatal(e)
			}
			original := route.NodeID
			calls, opens := 0, 0
			tr := stripeRoundTrip(func(*http.Request) (*http.Response, error) {
				calls++
				if calls == 1 && tc.status == 0 {
					return nil, errors.New("synthetic connection reset")
				}
				status, body := 200, `{}`
				if tc.status != 0 {
					status = tc.status
				}
				if tc.status == 402 {
					status, body = 402, `{"error":{"type":"card_error","code":"card_declined","decline_code":"generic_decline"}}`
				}
				return &http.Response{StatusCode: status, Header: http.Header{}, Body: io.NopCloser(strings.NewReader(body))}, nil
			})
			s := &stripeClient{http: &http.Client{Transport: tr}, vault: v, key: "pk_live_Test", route: route}
			s.openRoute = func(context.Context, json.RawMessage) (*http.Client, func(), error) {
				opens++
				return &http.Client{Transport: tr}, func() {}, nil
			}
			defer s.close()
			var out map[string]any
			before := time.Now()
			err := s.call(context.Background(), tc.method, tc.path, url.Values{}, "", &out)
			if calls != tc.wantCalls {
				t.Fatalf("calls=%d want=%d", calls, tc.wantCalls)
			}
			if tc.wantCalls == 2 {
				if err != nil || opens != 1 {
					t.Fatalf("safe request did not fail over: %v", err)
				}
			} else if err == nil || opens != 0 {
				t.Fatal("unsafe request replayed or lost failure")
			}
			nodes, _ := proxy.ParseOutboundPool([]byte(twoPaymentNodes))
			cooling := 0
			for _, node := range nodes {
				until, e := nodeCoolingUntil(v, node)
				if e != nil {
					t.Fatal(e)
				}
				if until > time.Now().Unix() {
					cooling++
					if until < before.Add(paymentNodeCooldown).Unix() || until > time.Now().Add(paymentNodeCooldown).Unix() {
						t.Fatal("cooldown duration wrong")
					}
				}
			}
			if cooling != tc.wantCooling {
				t.Fatalf("cooling=%d want=%d", cooling, tc.wantCooling)
			}
			saved, _ := readPaymentRoute(v, "1234")
			if (saved.NodeID != original) != (tc.wantCalls == 2) {
				t.Fatal("unexpected route mutation")
			}
		})
	}
}

const twoPaymentNodes = `[{"type":"http","tag":"a","server":"a.example.invalid","server_port":443},{"type":"http","tag":"b","server":"b.example.invalid","server_port":443}]`

