	Currency      string
}

var ErrNotEligible = errors.New("recipient cannot receive Premium gifts")
var ErrUserNotFound = errors.New("recipient was not found")
var ErrXReadFailure = errors.New("X account or price query failed")

// Eligibility is read-only: it neither creates a checkout nor submits a payment.
func Eligibility(ctx context.Context, v *vault.Vault, user string, port int) (string, error) {
	c, err := newXClient(v, port)
	if err != nil {
		return "", err
	}
	defer c.close()
	return c.recipient(ctx, user)
}

func (p Plan) Name() string { return fmt.Sprintf("Premium Gift - %d months", p.Months) }

type xClient struct {
	// Set only after validating an explicitly replaced public order.
	publicReplacement string
	publicRequestID   string
	publicGeneration  bool
	vault             *vault.Vault
	http              *http.Client
	regionalHTTP      *http.Client
	headers           http.Header
	readCheckout      func(context.Context, *Record) (*paymentPage, error)
	readCheckoutPaid  func(context.Context, *Record, Plan) (bool, error)
}

func newXClient(v *vault.Vault, port int) (*xClient, error) {
	raw, e := v.Get("api-auth")
	if e != nil {
		return nil, errors.New("X API authentication metadata is missing or unreadable")
	}
	defer clear(raw)
	var auth struct{ Authorization, UserAgent string }
	if json.Unmarshal(raw, &auth) != nil || !strings.HasPrefix(auth.Authorization, "Bearer ") {
		return nil, errors.New("invalid X API authentication metadata")
	}
	raw, e = v.Get("cookies")
	if e != nil {
		return nil, e
	}
	defer clear(raw)
	var state struct {
		Cookies []struct{ Name, Value, Domain string }
	}
	if e = json.Unmarshal(raw, &state); e != nil {
		return nil, e
	}
	h := http.Header{"Authorization": {auth.Authorization}, "User-Agent": {auth.UserAgent}, "Content-Type": {"application/json"}, "Origin": {"https://x.com"}, "X-Twitter-Auth-Type": {"OAuth2Session"}, "X-Twitter-Active-User": {"yes"}, "X-Twitter-Client-Language": {"en"}}
	found := map[string]bool{}
	for _, c := range state.Cookies {
		if c.Domain != ".x.com" && c.Domain != "x.com" {
			return nil, errors.New("unexpected cookie domain")
		}
		if c.Name != "auth_token" && c.Name != "ct0" {
			return nil, errors.New("unexpected cookie name")
		}
		if found[c.Name] || c.Value == "" || strings.ContainsAny(c.Value, "\r\n;") {
			return nil, errors.New("invalid X cookie")
		}
		found[c.Name] = true
		h.Add("Cookie", c.Name+"="+c.Value)
		if c.Name == "ct0" {
			h.Set("X-Csrf-Token", c.Value)
		}
	}
	if !found["ct0"] || !found["auth_token"] {
		return nil, errors.New("required X cookies missing")
	}
	// Account checks connect directly. Regional pricing and checkout creation
	// must share the configured exit because X prices depend on its country.
	newClient := func(proxy func(*http.Request) (*url.URL, error)) *http.Client {
		return &http.Client{Transport: &http.Transport{Proxy: proxy, TLSHandshakeTimeout: 15 * time.Second}, Timeout: 30 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return errors.New("unexpected X API redirect") }}
	}
	p, _ := url.Parse(fmt.Sprintf("http://127.0.0.1:%d", port))
	return &xClient{http: newClient(nil), regionalHTTP: newClient(http.ProxyURL(p)), headers: h, vault: v}, nil
}
func (c *xClient) close() {
	c.http.CloseIdleConnections()
	if c.regionalHTTP != nil {
		c.regionalHTTP.CloseIdleConnections()
	}
}
func (c *xClient) call(ctx context.Context, user, name, id string, variables any, mutation bool, out any) error {
	if mutation {
		return c.callOnce(ctx, user, name, id, variables, true, out)
	}
	return retrySafe(ctx, func() error { return c.callOnce(ctx, user, name, id, variables, false, out) })
}
func (c *xClient) callOnce(ctx context.Context, user, name, id string, variables any, mutation bool, out any) (callErr error) {
	// A fixed-operation audit is encrypted before sending, then completed even on
	// transport/body failures. Never store request headers or cookies here.
	var audit struct {
		Operation   string `json:"operation"`
		Variables   any    `json:"variables"`
		StartedAt   int64  `json:"started_at"`
		FinishedAt  int64  `json:"finished_at,omitempty"`
		Phase       string `json:"phase"`
		HTTP        int    `json:"http_status,omitempty"`
		Body        string `json:"body,omitempty"`
		Cause       string `json:"cause,omitempty"`
		Failure     string `json:"failure,omitempty"`
		ContentType string `json:"content_type,omitempty"`
		RequestID   string `json:"request_id,omitempty"`
		EdgeID      string `json:"edge_id,omitempty"`
	}
	audit.Operation, audit.Variables, audit.StartedAt, audit.Phase = name, variables, time.Now().Unix(), "request_pending"
	if !mutation {
		defer func() {
			if callErr == nil {
				return
			}
			audit.FinishedAt, audit.Failure = time.Now().Unix(), callErr.Error()
			if len(audit.Body) > 32<<10 {
				audit.Body = audit.Body[:32<<10]
			}
			b, err := json.Marshal(audit)
			defer clear(b)
			if err != nil || c.vault.Put(fmt.Sprintf("x-read-failure:%s:%s:%d", user, name, time.Now().UnixNano()), b) != nil {
				callErr = fmt.Errorf("%w: could not preserve failure details", ErrXReadFailure)
				return
			}
			callErr = fmt.Errorf("%w: %w", ErrXReadFailure, callErr)
		}()
	}
	if mutation {
		key := fmt.Sprintf("x-create-attempt:%s:%d", user, time.Now().UnixNano())
		persist := func() error {
			b, e := json.Marshal(audit)
			if e != nil {
				return e
			}
			defer clear(b)
			return c.vault.Put(key, b)
		}
		if e := persist(); e != nil {
			return errors.New("could not preserve X creation attempt before sending")
		}
		defer func() {
			audit.FinishedAt = time.Now().Unix()
			if callErr != nil {
				audit.Failure = callErr.Error()
			}
			if e := persist(); e != nil {
				callErr = errors.New("could not preserve X creation outcome; automatic recovery blocked")
			}
		}()
	}
	target := "https://x.com/i/api/graphql/" + id + "/" + name
	method := "GET"
	var body []byte
	if mutation {
		method = "POST"
		body, _ = json.Marshal(map[string]any{"variables": variables, "queryId": id})
	} else {
		b, _ := json.Marshal(variables)
		q := url.Values{"variables": {string(b)}}
		if name == "useSubscriptionProductDetailsByRestIdQuery" {
			q.Set("features", `{"subscriptions_marketing_page_fetch_promotions":true}`)
		}
		target += "?" + q.Encode()
	}
	req, e := http.NewRequestWithContext(ctx, method, target, bytes.NewReader(body))
	if e != nil {
		return e
	}
	req.Header = c.headers.Clone()
	req.Header.Set("Referer", "https://x.com/"+user+"/gift-premium")
	client := c.http
	if mutation || name == "useSubscriptionProductDetailsByRestIdQuery" {
		if c.regionalHTTP == nil {
			return errors.New("X regional checkout proxy is unavailable")
		}
		client = c.regionalHTTP
	}
	res, e := client.Do(req)
	if e != nil {
		audit.Phase, audit.Cause = "transport_failed", e.Error()
		return temporary(fmt.Errorf("X %s request failed", name))
	}
	audit.HTTP, audit.Phase = res.StatusCode, "response_received"
	audit.ContentType, audit.RequestID, audit.EdgeID = res.Header.Get("Content-Type"), res.Header.Get("X-Request-ID"), res.Header.Get("CF-Ray")
	defer res.Body.Close()
	raw, e := io.ReadAll(io.LimitReader(res.Body, (2<<20)+1))
	defer clear(raw)
	if len(raw) > 2<<20 {
		audit.Body = string(raw[:2<<20])
		audit.Phase = "response_too_large"
		return errors.New("X response exceeded size limit")
	}
	audit.Body = string(raw)
	if e != nil {
		audit.Phase, audit.Cause = "response_read_failed", e.Error()
		if res.StatusCode >= 400 && res.StatusCode < 500 {
			return xHTTPFailure(errors.New("X error response could not be read"), res.StatusCode, res.Header.Get("Retry-After"), mutation)
		}
		return temporary(errors.New("X response could not be read"))
	}
	audit.Phase = "response_validation"
	if res.StatusCode != 200 {
		return xHTTPFailure(fmt.Errorf("X %s returned HTTP %d; no payment attempted", name, res.StatusCode), res.StatusCode, res.Header.Get("Retry-After"), mutation)
	}
	var envelope struct {
		Errors []json.RawMessage `json:"errors"`
	}
	if e = json.Unmarshal(raw, &envelope); e != nil {
		return errors.New("X returned non-JSON data")
	}
	if len(envelope.Errors) > 0 {
		return fmt.Errorf("X %s rejected the operation", name)
	}
	if e = json.Unmarshal(raw, out); e != nil {
		return e
	}
	audit.Phase = "response_decoded"
	return nil
}

// A 403 on a read-only X query can be transient. Retry within the existing
// bounded budget and Retry-After rules, without changing credentials or proxy.
// Never apply this exception to checkout creation or Stripe confirmation.
func xHTTPFailure(err error, status int, retryAfter string, mutation bool) error {
	if status == http.StatusForbidden && !mutation {
		return httpFailure(err, http.StatusTooManyRequests, retryAfter)
	}
	return httpFailure(err, status, retryAfter)
}

func (c *xClient) recipient(ctx context.Context, user string) (string, error) {
	return c.identity(ctx, user, true)
}
func (c *xClient) identity(ctx context.Context, user string, requireEligible bool) (string, error) {
	var r struct {
		Data struct {
			User struct {
				Result struct {
					ID       string `json:"rest_id"`
					Eligible bool   `json:"premium_gifting_eligible"`
					Core     struct {
						Screen string `json:"screen_name"`
					} `json:"core"`
				} `json:"result"`
			} `json:"user"`
		} `json:"data"`
	}
	if e := c.call(ctx, user, "PremiumGiftingQuery", "kn8hCE6bHstQV2MtfYDTKg", map[string]string{"screenName": user}, false, &r); e != nil {
		return "", e
	}
	u := r.Data.User.Result
	if u.ID == "" {
		return "", ErrUserNotFound
	}
	if !strings.EqualFold(u.Core.Screen, user) {
		return "", errors.New("recipient identity or gift eligibility could not be verified")
	}
	if requireEligible && !u.Eligible {
		return "", ErrNotEligible
	}
	return u.ID, nil
}
func (c *xClient) quote(ctx context.Context, user string, p Plan) error {
	var r struct {
		Data struct {
			Product struct {
				ID     string `json:"rest_id"`
				Prices []struct {
					Amount   int64  `json:"amount_local_micro"`
					Currency string `json:"currency_code"`
					Type     string `json:"price_type"`
				} `json:"prices"`
			} `json:"web_subscription_product_details_by_rest_id"`
		} `json:"data"`
	}
	if e := c.call(ctx, user, "useSubscriptionProductDetailsByRestIdQuery", "Se1Bp6zcNnuXYXRecV2qLA", map[string]string{"stripeId": p.ProductID}, false, &r); e != nil {
		return e
	}
	product := r.Data.Product
	if product.ID != p.ProductID || len(product.Prices) != 1 {
		return errors.New("unexpected X product or price list")
	}
	price := product.Prices[0]
	if price.Type != "OneTime" || !strings.EqualFold(price.Currency, p.Currency) || price.Amount != int64(p.Minor)*10000 {
		return errors.New("X price is not exactly the allowed one-time amount")
	}
	return nil
}
func (c *xClient) create(ctx context.Context, user, recipient string, p Plan) (string, string, error) {
	if err := c.checkCreation(ctx, time.Now()); err != nil {
		return "", "", err
	}
	if err := reserveCheckoutCreation(c.vault, time.Now()); err != nil {
		return "", "", err
	}
	var r struct {
		Data struct {
			Gift struct {
				ID     string `json:"session_id"`
				URL    string `json:"session_url"`
				Status string `json:"session_status"`
			} `json:"onetimepurchase_gift"`
		} `json:"data"`
	}
	variables := map[string]string{"cancel_url": "https://x.com/" + user + "/gift-premium", "success_url": "https://x.com/" + user + "/gift-premium/success", "external_product_id": p.ProductID, "gift_recipient": recipient}
	if e := c.call(ctx, user, "useOneTimePurchaseGiftMutation", "GqTVJ4S1526tLkxj69xIZw", variables, true, &r); e != nil {
		return "", "", e
	}
	s := r.Data.Gift
	if s.Status != "Unpaid" {
		return "", "", errors.New("X checkout status is not Unpaid; payment was not submitted")
	}
	if !sessionPattern.MatchString(s.ID) {
		return "", "", errors.New("X checkout session ID is missing or not a live session; payment was not submitted")
	}
	if !sessionURL(s.URL, s.ID) {
		return "", "", errors.New("X checkout URL is unsupported or does not match its session; payment was not submitted")
	}
	return s.ID, s.URL, nil
}

package site

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"
	"xgift/internal/checkout"
)

func (s *server) paymentsAvailable() (bool, error) {
	if !s.payments {
		return false, nil
	}
	paused, err := checkout.PaymentPaused(s.vault)
	return !paused && err == nil, err
}

// catalogPlan resolves the configured plan per flow, never at startup, so the
// site boots before the operator writes the catalog record.
func (s *server) catalogPlan(months int) (checkout.Plan, error) {
	catalog, err := checkout.ReadCatalog(s.vault)
	if err != nil {
		return checkout.Plan{}, err
	}
	return catalog.PlanFor(months)
}

// A status query can repair delayed/lost success writes, but can never pay.
func (s *server) reconcileStatus(ctx context.Context, c *codeRow) {
	if c.Status != "review" || c.RecipientID == "" {
		return
	}
	release, ok := s.tryLock()
	if !ok {
		return
	}
	defer release()
	ctx, cancel := context.WithTimeout(ctx, 35*time.Second)
	defer cancel()
	record, err := checkout.Reconcile(ctx, s.vault, c.RecipientID, s.port)
	if record != nil && record.Status != "succeeded" && checkout.IsPaymentDeclined(record) && record.RecipientID == c.RecipientID && record.Username == c.Username && record.Months == c.Months {
		msg := "付款被支付机构拒绝，本次兑换未完成。请联系管理员处理，请勿重复提交。"
		if _, e := s.db.Exec("UPDATE codes SET message=? WHERE id=? AND status='review' AND recipient_id=? AND username=? AND months=?", msg, c.ID, c.RecipientID, c.Username, c.Months); e == nil {
			c.Message = msg
		}
		return
	}
	if err != nil || record == nil || record.Status != "succeeded" || record.RecipientID != c.RecipientID || record.Username != c.Username || record.Months != c.Months {
		return
	}
	plan, err := s.catalogPlan(c.Months)
	if err != nil || record.Amount != plan.Minor || record.Currency != strings.ToUpper(plan.Currency) {
		return
	}
	msg := fmt.Sprintf("已为 @%s 完成 %d 个月 Premium 赠送。打开 X 查看会员状态；如未刷新，请重新打开 X。", c.Username, c.Months)
	result, err := s.db.Exec("UPDATE codes SET status='succeeded',progress=100,message=?,updated=? WHERE id=? AND recipient_id=? AND username=? AND months=? AND status='review'", msg, time.Now().Unix(), c.ID, c.RecipientID, c.Username, c.Months)
	if err != nil {
		return
	}
	n, err := result.RowsAffected()
	if err == nil && n == 1 {
		c.Status = "succeeded"
		c.Progress = 100
		c.Message = msg
	}
}

// Background reconciliation never creates an order or submits payment. It checks
// one pending record per tick with a short deadline, yielding to live checkouts.
func (s *server) reconcileLoop() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	cursor := ""
	for {
		select {
		case <-s.ctx.Done():
			return
		case <-ticker.C:
		}
		var c codeRow
		err := s.db.QueryRow("SELECT id,recipient_id,username,months,status,progress,updated FROM codes WHERE status='review' AND recipient_id IS NOT NULL AND id>? ORDER BY id LIMIT 1", cursor).Scan(&c.ID, &c.RecipientID, &c.Username, &c.Months, &c.Status, &c.Progress, &c.Updated)
		if err != nil {
			cursor = ""
			continue
		}
		cursor = c.ID
		ctx, cancel := context.WithTimeout(s.ctx, 8*time.Second)
		s.reconcileStatus(ctx, &c)
		cancel()
	}
}

func (s *server) autoChecking(c *codeRow) bool {
	if c.Status != "review" || c.RecipientID == "" || c.Updated < time.Now().Add(-7*24*time.Hour).Unix() {
		return false
	}
	raw, err := s.vault.Get("checkout:" + c.RecipientID)
	if err != nil {
		return false
	}
	defer clear(raw)
	var r checkout.Record
	if json.Unmarshal(raw, &r) != nil {
		return false
	}
	return !checkout.IsPaymentDeclined(&r) && r.RecipientID == c.RecipientID && r.Username == c.Username && r.Months == c.Months && r.SubmittedAt > 0 && (r.Status == "unknown" || r.Status == "submitting")
}

func (s *server) paymentDeclined(c *codeRow) bool {
	if c.Status != "review" || c.RecipientID == "" {
		return false
	}
	raw, err := s.vault.Get("checkout:" + c.RecipientID)
	if err != nil {
		return false
	}
	defer clear(raw)
	var record checkout.Record
	return json.Unmarshal(raw, &record) == nil && record.RecipientID == c.RecipientID && record.Username == c.Username && record.Months == c.Months && checkout.IsPaymentDeclined(&record)
}

package checkout

import (
	"context"
	"encoding/json"
	"errors"
	"net/url"
	"regexp"
	"strconv"
	"strings"
	"xgift/internal/vault"
)

// Reconcile only queries the existing session. The caller must hold checkout.lock.
func Reconcile(ctx context.Context, v *vault.Vault, recipient string, port int) (*Record, error) {
	raw, err := v.Get("checkout:" + recipient)
	if err != nil {
		return nil, err
	}
	defer clear(raw)
	var r Record
	if err = json.Unmarshal(raw, &r); err != nil {
		return nil, err
	}
	catalog, err := ReadCatalog(v)
	if err != nil {
		return nil, err
	}
	plan, err := catalog.PlanFor(r.Months)
	if err != nil {
		return nil, err
	}
	if r.RecipientID != recipient || r.Amount != plan.Minor || r.Currency != strings.ToUpper(plan.Currency) || r.ProductID != plan.ProductID || !usernamePattern.MatchString(r.Username) || !sessionURL(r.URL, r.SessionID) {
		return nil, errors.New("recorded order identity or price mismatch")
	}
	if r.Status == "succeeded" {
		return &r, nil
	}
	if r.Status != "created" && r.Status != "unknown" && r.Status != "submitting" && r.Status != "requires_action" && !IsPaymentDeclined(&r) {
		return &r, errors.New("order has no submitted payment to reconcile")
	}
	if !unsubmitted(&r) {
		if err = verifySubmission(v, &r, plan); err != nil {
			return &r, err
		}
	}
	r.LinkBlocked = true
	if err = save(v, &r); err != nil {
		return &r, err
	}
	s, err := newStripe(ctx, v, r.RecipientID, paymentRead)
	if err != nil {
		return &r, err
	}
	defer s.close()
	status := "pending"
	if unsubmitted(&r) {
		var paid bool
		paid, err = s.verifiedCheckoutPaid(ctx, &r, plan)
		if paid {
			status = "succeeded"
		}
	} else {
		status, err = s.poll(ctx, &r, plan)
	}
	if err != nil {
		return &r, err
	}
	if status == "requires_action" {
		r.Status = status
		if err = save(v, &r); err != nil {
			return &r, err
		}
		if err = markAuthenticationRequired(v, &r); err != nil {
			return &r, err
		}
	}
	if status != "succeeded" {
		return &r, errors.New("payment is not yet confirmed successful")
	}
	r.Status = "succeeded"
	r.LastError = nil
	if err = save(v, &r); err != nil {
		return &r, err
	}
	return &r, paymentOutcome(v, &r)
}

func verifySubmission(v *vault.Vault, r *Record, plan Plan) error {
	f, err := url.ParseQuery(r.ConfirmParameters)
	if err != nil || len(f) != 5 || r.SubmittedAt < r.Created || r.SubmittedAt == 0 || !regexp.MustCompile(`^pm_[A-Za-z0-9]+$`).MatchString(r.PaymentMethod) || r.ConfirmKey != idempotency(r, "confirm") {
		return errors.New("missing or inconsistent original confirmation evidence")
	}
	expected := map[string]string{"payment_method": r.PaymentMethod, "expected_amount": strconv.Itoa(plan.Minor), "expected_payment_method_type": "card", "init_checksum": f.Get("init_checksum"), "return_url": "https://x.com/" + r.Username + "/gift-premium/success"}
	if expected["init_checksum"] == "" {
		return errors.New("missing original checksum")
	}
	for k, value := range expected {
		if len(f[k]) != 1 || f.Get(k) != value {
			return errors.New("original confirmation parameters mismatch")
		}
	}
	// Legacy records were produced by the same guard-before-confirm flow, but did
	// not retain a separate snapshot. Never manufacture historical Stripe evidence.
	if r.ManualRecovery {
		b, err := v.Get(manualProofKey(r))
		if err != nil {
			return err
		}
		defer clear(b)
		var proof manualProof
		if err = json.Unmarshal(b, &proof); err != nil {
			return err
		}
		if err = proof.guard(r, plan); err != nil {
			return err
		}
		var page paymentPage
		if err = json.Unmarshal(proof.Page, &page); err != nil {
			return err
		}
		if page.Checksum != f.Get("init_checksum") {
			return errors.New("manual preflight checksum mismatch")
		}
		return nil
	}
	if r.PreflightSaved {
		raw, err := v.Get("stripe-preflight:" + r.SessionID)
		if err != nil {
			return err
		}
		defer clear(raw)
		var p paymentPage
		if err = json.Unmarshal(raw, &p); err != nil {
			return err
		}
		if err = p.guard(r, plan, true); err != nil {
			return err
		}
		if p.Checksum != f.Get("init_checksum") {
			return errors.New("preflight checksum mismatch")
		}
	}
	return nil
}

func (s *stripeClient) poll(ctx context.Context, r *Record, plan Plan) (string, error) {
	if err := verifySubmission(s.vault, r, plan); err != nil {
		return "", err
	}
	var raw json.RawMessage
	if err := s.call(ctx, "GET", "payment_pages/"+r.SessionID+"/poll", url.Values{}, "", &raw); err != nil {
		return "", err
	}
	defer clear(raw)
	var p struct {
		SessionID     string  `json:"session_id"`
		Live          bool    `json:"livemode"`
		Sandbox       *bool   `json:"is_sandbox_merchant"`
		Mode          string  `json:"mode"`
		State         string  `json:"state"`
		PaymentStatus string  `json:"payment_object_status"`
		SuccessURL    string  `json:"success_url"`
		Currency      *string `json:"currency"`
		Amount        *int    `json:"amount"`
		AccountID     *string `json:"account_id"`
	}
	if err := json.Unmarshal(raw, &p); err != nil {
		return "", err
	}
	if p.SessionID != r.SessionID || !p.Live || p.Sandbox == nil || *p.Sandbox || p.Mode != "payment" || p.SuccessURL != "https://x.com/"+r.Username+"/gift-premium/success" {
		return "", errors.New("Stripe result session or recipient mismatch")
	}
	if (p.Currency != nil && *p.Currency != plan.Currency) || (p.Amount != nil && *p.Amount != plan.Minor) || (p.AccountID != nil && *p.AccountID != plan.Merchant) {
		return "", errors.New("Stripe result price or merchant mismatch")
	}
	if err := s.vault.Put("stripe-result:"+r.SessionID, raw); err != nil {
		return "", err
	}
	if p.State == "succeeded" && p.PaymentStatus == "succeeded" {
		return "succeeded", nil
	}
	if p.PaymentStatus == "requires_action" {
		return "requires_action", nil
	}
	return "pending", nil
}

